import { signal, mount } from 'kerfjs';
import { delegateActions } from 'kerfjs/actions';
import { MenuHeader } from '@kerfjs/ui/menu-header';
import { MenuItem } from '@kerfjs/ui/menu-item';
import { LucideIcon } from '@kerfjs/ui/lucide-icon';
import { Toolbar } from '@kerfjs/ui/toolbar';
import { ToolbarControlGroup } from '@kerfjs/ui/toolbar-control-group';
import { Inbox, Folder, Plus, Settings } from 'lucide';
import '@kerfjs/ui/layout.css';
import '@kerfjs/ui/sidebar.css';
import './navigation.css';

export function mountNavigation(root: HTMLElement, app: { navigate(id: string): void; addProject(): void; settings(): void }) {
 const selected = signal('inbox');
 const stopMount = mount(root, () => <aside class="navigation kui-layout">
  <nav class="kui-sidebar kui-scroll-owner" aria-label="Main navigation">
   <section class="kui-sidebar-section">
    <MenuHeader label="Workspace" />
    <MenuItem label="Inbox" action="navigate" itemId="inbox" selected={selected.value === 'inbox'} icon={<LucideIcon icon={Inbox} name="inbox" />} />
    <MenuItem label="Drafts" action="navigate" itemId="drafts" selected={selected.value === 'drafts'} />
   </section>
   <section class="kui-sidebar-section">
    <MenuHeader label="Projects" />
    <MenuItem label="Design system" action="navigate" itemId="design" selected={selected.value === 'design'} icon={<LucideIcon icon={Folder} name="folder" />} multiline />
    <MenuItem label="Archived — administrators only" action="navigate" itemId="archive" disabled />
    <div class="kui-sidebar-surface"><strong>Workspace summary</strong><p>Three active projects · Team workspace</p></div>
   </section>
  </nav>
  <footer><Toolbar label="Sidebar actions" divider={false}
   leading={<ToolbarControlGroup appearance="borderless" single label="Create"><button type="button" data-action="add" aria-label="Add project"><LucideIcon icon={Plus} name="plus" /></button></ToolbarControlGroup>}
   trailing={<ToolbarControlGroup appearance="borderless" single label="Settings"><button type="button" data-action="settings" aria-label="Workspace settings"><LucideIcon icon={Settings} name="settings" /></button></ToolbarControlGroup>} />
  </footer>
 </aside>);
 const stopActions = delegateActions(root, 'click', {
  navigate: (_event, element) => { const id = (element as HTMLElement).dataset.itemId; if (id && id !== 'archive') { selected.value = id; app.navigate(id); } },
  add: () => app.addProject(), settings: () => app.settings()
 });
 return () => { stopActions(); stopMount(); };
}

