.navigation { width: min(22rem, 100%); height: 100%; min-height: 0; display: grid; grid-template-rows: minmax(0,1fr) auto; color: var(--kui-color-text); background: var(--kui-color-surface); }
.navigation > nav { min-height: 0; }
.navigation > footer { border-block-start: 1px solid var(--kui-color-border); }
